package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class RoadClipTest {
 static NativeRoadAttributes[] tables;static DataOutputStream records;static int cases,accepted,rejected,empty;
 static byte[] raw(int n,int shift,int height,int affine,int offsetU,int offsetV,Random random){ByteBuffer b=ByteBuffer.allocate(288).order(ByteOrder.LITTLE_ENDIAN);b.putInt(n).putInt(shift).putInt(height).putInt(affine).putInt(0x08001000).putInt(0x02000002).putInt(offsetU).putInt(offsetV);for(int i=0;i<n&&i<32;i++)b.putInt(random.nextInt()).putInt(random.nextInt());return b.array();}
 static void emit(int flag,double[][] points,byte[] raw)throws Exception{double[][] before=new double[points.length][];for(int i=0;i<points.length;i++)before[i]=points[i].clone();byte[] original=raw.clone();double[][] ring=new double[0][];boolean good=true;try{ring=NativeRoadClip.clip(points,ByteBuffer.wrap(raw),tables[flag]);}catch(IllegalArgumentException bad){good=false;}if(!Arrays.deepEquals(before,points)||!Arrays.equals(original,raw))throw new AssertionError("Ring input mutation");records.writeInt(flag);records.writeInt(points.length);records.write(raw);for(double[] p:points)for(double v:p)records.writeDouble(v);records.writeInt(good?1:0);records.writeInt(ring.length);for(double[] p:ring)for(double v:p)records.writeDouble(v);cases++;if(good){accepted++;if(ring.length==0)empty++;}else rejected++;}
 public static void main(String[] args)throws Exception{Path out=Paths.get(args[0]);Files.createDirectories(out);byte[] table=Files.readAllBytes(Paths.get(args[1])),missing=table.clone();ByteBuffer.wrap(missing).order(ByteOrder.LITTLE_ENDIAN).putInt(64*4,0);tables=new NativeRoadAttributes[]{new NativeRoadAttributes(ByteBuffer.wrap(table)),new NativeRoadAttributes(ByteBuffer.wrap(missing))};ByteArrayOutputStream bytes=new ByteArrayOutputStream();records=new DataOutputStream(bytes);Random random=new Random(5901);
  double[][][] shapes={{{-30,-10,32},{30,-10,100},{5,0,100},{30,30,100},{-30,30,100}},{{-10,-10,64},{10,-10,64},{0,10,64}},{{-10,0,-100000},{10,0,-99999},{0,10,-99998}},{{-10,0,100},{10,0,200},{0,10,300}},{{-10,0,63.9999},{10,0,64.0001},{0,10,100}}};
  for(int flag=0;flag<2;flag++)for(int affine=0;affine<2;affine++)for(double[][] points:shapes){emit(flag,points,raw(points.length,6,128,affine,-32768,32767,random));double[][] reversed=new double[points.length][];for(int i=0;i<points.length;i++)reversed[i]=points[points.length-1-i];emit(flag,reversed,raw(points.length,6,128,affine,32767,-32768,random));}
  for(int caseIndex=0;caseIndex<160;caseIndex++){int n=3+random.nextInt(30);double[][] points=new double[n][3];for(int i=0;i<n;i++){double angle=i*Math.PI*2/n;points[i]=new double[]{Math.cos(angle)*(10+random.nextDouble()*100),Math.sin(angle)*(10+random.nextDouble()*100),-50+random.nextDouble()*350};}emit(0,points,raw(n,random.nextInt(11),2*(1+random.nextInt(1024)),random.nextInt(2),random.nextInt(65536)-32768,random.nextInt(65536)-32768,random));}
  emit(0,shapes[3],raw(4,6,128,0,0,0,random));emit(0,shapes[3],raw(3,11,128,0,0,0,random));emit(0,shapes[3],raw(3,6,3,0,0,0,random));emit(0,shapes[3],raw(3,6,128,2,0,0,random));emit(0,new double[][]{{Double.NaN,0,32},{10,0,100},{0,10,100}},raw(3,6,128,0,0,0,random));emit(0,new double[][]{{0,0,-40000},{10,0,100},{0,10,100}},raw(3,6,128,0,0,0,random));
  int fixture=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[2]),"*.nsp")){for(Path file:files){if(file.getFileName().toString().startsWith("bad-"))continue;NativeWorldScene w=new NativeWorldScene(new NativeScenePacket(1,Files.readAllBytes(file)));for(int si=0;si<w.surfaceCount();si++){NativeWorldScene.Surface s=w.surface(si);ByteBuffer attributes=s.sourceAttributes();if(attributes==null)continue;fixture++;byte[] r=new byte[288];attributes.get(r);double[][] points=new double[s.corners][3];ByteBuffer source=s.vertices();for(int i=0;i<s.corners;i++)points[i]=new double[]{source.getDouble(i*24),source.getDouble(i*24+8),32+i*40.25};emit(0,points,r);}}}
  records.close();try(DataOutputStream stream=new DataOutputStream(Files.newOutputStream(out.resolve("road-clip-cases.bin")))){stream.writeInt(0x3143504e);stream.writeInt(cases);stream.write(bytes.toByteArray());}if(accepted==0||rejected==0||empty==0||fixture!=4)throw new AssertionError("Missing ring cases");System.out.println("PASS_ROAD_CLIP_CASES cases="+cases+" accepted="+accepted+" rejected="+rejected+" empty="+empty+" fixture_surfaces="+fixture+" input_immutable=true");
 }
}
